/// An action line, which is the first line of each operation in a bulk request.
/// It specifies the action to perform (`index`, `create`, `update`, or `delete`) and its metadata, such as the target index and document ID.
/// All actions except `delete` expect a source line to follow.
#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub enum OperationContainer {
    /// Index the specified document.
    /// If the document exists, it replaces the document and increments the version.
    /// The following line must contain the source data to be indexed.
    #[serde(rename = "index")]
    Index(IndexOperation),
    /// Index the specified document if it does not already exist.
    /// The following line must contain the source data to be indexed.
    #[serde(rename = "create")]
    Create(CreateOperation),
    /// Perform a partial document update.
    /// The following line must contain the partial document and update options.
    #[serde(rename = "update")]
    Update(UpdateOperation),
    /// Remove the specified document from the index.
    #[serde(rename = "delete")]
    Delete(DeleteOperation),
}

impl From<IndexOperation> for OperationContainer {
    fn from(value: IndexOperation) -> Self {
        OperationContainer::Index(value)
    }
}

impl From<CreateOperation> for OperationContainer {
    fn from(value: CreateOperation) -> Self {
        OperationContainer::Create(value)
    }
}

impl From<UpdateOperation> for OperationContainer {
    fn from(value: UpdateOperation) -> Self {
        OperationContainer::Update(value)
    }
}

impl From<DeleteOperation> for OperationContainer {
    fn from(value: DeleteOperation) -> Self {
        OperationContainer::Delete(value)
    }
}

impl From<IndexOperationBuilder> for OperationContainer {
    fn from(builder: IndexOperationBuilder) -> Self {
        builder.build().into()
    }
}

